// Aggregate today's numbers per branch (runs once with all items)
const t=new Date().toISOString().slice(0,10);
const byBranch={};
for (const it of items) {
  const b = it.json._branch || $('Read branches').all()[it.pairedItem?.item||0]?.json?.Name || 'Branch';
  byBranch[b]=byBranch[b]||{orders:0,rev:0};
  if ((it.json.Date||'').startsWith(t)) { byBranch[b].orders++; byBranch[b].rev += Number(String(it.json.Amount||'').replace(/[^0-9.]/g,''))||0; }
}
const rows=Object.entries(byBranch);
const tot=rows.reduce((s,[,v])=>({o:s.o+v.orders,r:s.r+v.rev}),{o:0,r:0});
return [{ json: { Date:t, text: '🏢 GROUP DAILY ROLLUP — '+t+'\n'+rows.map(([b,v])=>`• ${b}: ${v.orders} sales · ₹${v.rev.toLocaleString('en-IN')}`).join('\n')+`\n━━━━━━━━\nTOTAL: ${tot.o} sales · ₹${tot.r.toLocaleString('en-IN')}` , Total:tot.r } }];

